{
  "items": [
    {
      "name": "Polynomial.degree_sub_lt",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Definitions",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Ring R] {p q : Polynomial R},\n  p.degree = q.degree → p ≠ 0 → p.leadingCoeff = q.leadingCoeff → (p - q).degree < p.degree"
    },
    {
      "name": "Polynomial.IsMonicOfDegree.natDegree_sub_lt",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.IsMonicOfDegree",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Ring R] {p q : Polynomial R} {n : ℕ},\n  n ≠ 0 → p.IsMonicOfDegree n → q.IsMonicOfDegree n → (p - q).natDegree < n"
    },
    {
      "name": "Polynomial.degree_sub_eq_left_of_degree_lt",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Operations",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Ring R] {p q : Polynomial R}, q.degree < p.degree → (p - q).degree = p.degree"
    },
    {
      "name": "Polynomial.natDegree_cancelLeads_lt_of_natDegree_le_natDegree_of_comm",
      "module_name": "Mathlib.Algebra.Polynomial.CancelLeads",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Ring R] {p q : Polynomial R},\n  p.leadingCoeff * q.leadingCoeff = q.leadingCoeff * p.leadingCoeff →\n    p.natDegree ≤ q.natDegree → 0 < q.natDegree → (p.cancelLeads q).natDegree < q.natDegree"
    },
    {
      "name": "Polynomial.degree_sub_eq_right_of_degree_lt",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Operations",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Ring R] {p q : Polynomial R}, p.degree < q.degree → (p - q).degree = q.degree"
    }
  ]
}
